            this.nbrStart = new Int32Array(n + 1);
        }
        let idx = this.nbrIdx;
        idx.length = 0;
        for(let i=0; i<n; i++){
            this.nbrStart[i] = idx.length;
            let pos = ps[i].position;
            let gx = (pos.x / cell) | 0;
            let gy = (pos.y / cell) | 0;
            for(let dx=-1; dx<=1; dx++){
                for(let dy=-1; dy<=1; dy++){
                    let content = map.get(grid.cellIndexToHash(gx + dx, gy + dy));
                    if(content){
                        for(let m=0; m<content.length; m++){
                            let j = content[m];
                            if(j !== i){
                                idx.push(j);
                            }
                        }
                    }
                }
            }
        }
        this.nbrStart[n] = idx.length;
    }

    applyGravity(dt){
        for(let i=0; i< this.particles.length; i++){
            let p = this.particles[i];
            p.agitation = 0;   // re-measured each step in viscosity()
            p.cover = 0;       // how much beer sits on top of this particle
            p.velocity = Add(p.velocity, Scale(this.GRAVITY, dt));

            // Foam is lighter than beer: foamy particles float up and gather as a head.
            if(p.foam > 0.04 && this.isInsideGlassInterior(p.position)){
                p.velocity.y -= this.GRAVITY.y * this.FOAM_BUOYANCY * p.foam * dt;
            }
        }
    }

    applyBeerForces(dt){
        let glassVolume = this.glassVolL;
        let overflow = Math.max(0, (glassVolume - this.GLASS_CAPACITY_L) / this.GLASS_CAPACITY_L);
        let rimOut = new Vector2(-0.78, -0.18);
        rimOut.Normalize();

        for(let i=0; i<this.particles.length; i++){
            let particle = this.particles[i];
            if(this.isInsideGlassInterior(particle.position)){
                particle.velocity = Scale(particle.velocity, 0.999);

                if(overflow > 0){
                    let local = this.worldToGlassLocal(particle.position);
                    let surfaceBias = Math.max(0, 1 - (local.y + this.glass.height * 0.5) / (this.glass.height * 0.42));
                    particle.velocity = Add(particle.velocity, Scale(rimOut, overflow * surfaceBias * dt * 8));
                }
            }
        }
    }

    predictPositions(dt){
        for(let i=0; i< this.particles.length; i++){
            this.particles[i].prevPosition = this.particles[i].position.Cpy();
            let positionDelta = Scale(this.particles[i].velocity, dt * this.VELOCITY_DAMPING);
            this.particles[i].position = Add(this.particles[i].position, positionDelta);
        }
    }

    computeNextVelocity(dt){
        for(let i=0; i< this.particles.length; i++){
            let velocity = Scale(Sub(this.particles[i].position, this.particles[i].prevPosition), 1.0 / dt);
            this.particles[i].velocity = velocity;
        }
    }

    handleOneWayCoupling(dt){
        for(let i=0; i< this.particles.length; i++){
            let particle = this.particles[i];
            for(let j=0; j<this.shapes.length;j++){
                let dir = this.shapes[j].getDirectionOut(particle.position);
                if(dir != null){
                    let pen = dir.Length();
                    particle.position = Add(particle.position, dir);
                    if(pen > 0.0001){
                        // Slippery wall: cancel only the into-wall motion, keep the beer
                        // sliding down the glass instead of clinging to the edge.
                        let n = Scale(dir, 1 / pen);
                        let vn = particle.velocity.Dot(n);
                        if(vn < 0){
                            particle.velocity = Sub(particle.velocity, Scale(n, vn));
                        }
                        particle.velocity = Scale(particle.velocity, 0.99);
                        particle.prevPosition = Sub(particle.position, Scale(particle.velocity, dt));
                    }
                }
            }
        }
    }

    doubleDensityRelaxation(dt){
        let ps = this.particles;
        let nbr = this.nbrIdx;
        let start = this.nbrStart;
        let R = this.INTERACTION_RADIUS;
        let R2 = R * R;
        let invR = 1 / R;
        let dt2 = dt * dt;
        let K = this.K;
        let KNEAR = this.K_NEAR;
        let REST = this.REST_DENSITY;

        for(let i=0; i<ps.length; i++){
            let pa = ps[i];
            let pax = pa.position.x;
            let pay = pa.position.y;
            let s = start[i];
            let e = start[i+1];

            let density = 0;
            let densityNear = 0;
            for(let k=s; k<e; k++){
                let pb = ps[nbr[k]];
                let rx = pb.position.x - pax;
                let ry = pb.position.y - pay;
                let d2 = rx*rx + ry*ry;
                if(d2 < R2){
                    let omq = 1 - Math.sqrt(d2) * invR;
                    density += omq*omq;
                    densityNear += omq*omq*omq;
                }
            }

            let pressure = K * (density - REST);
            let pressureNear = KNEAR * densityNear;
            let dax = 0;
            let day = 0;

            for(let k=s; k<e; k++){
                let pb = ps[nbr[k]];
                let rx = pb.position.x - pax;
                let ry = pb.position.y - pay;
                let d2 = rx*rx + ry*ry;
                if(d2 >= R2){
                    continue;
                }
                let dist = Math.sqrt(d2);
                if(dist < 0.0001){
                    rx = Math.random() - 0.5;
                    ry = Math.random() - 0.5;
                    dist = Math.sqrt(rx*rx + ry*ry);
                }
                let omq = 1 - dist * invR;
                let disp = dt2 * (pressure * omq + pressureNear * omq * omq);
                let f = 0.5 * disp / dist;
                let dx = rx * f;
                let dy = ry * f;
                pb.position.x += dx;
                pb.position.y += dy;
                dax -= dx;
                day -= dy;
            }

            pa.position.x += dax;
            pa.position.y += day;
        }
    }

    viscosity(dt){
        let ps = this.particles;
        let nbr = this.nbrIdx;
        let start = this.nbrStart;
        let R = this.INTERACTION_RADIUS;
        let R2 = R * R;
        let invR = 1 / R;
        let SIG = this.SIGMA;
        let BET = this.BETA;

        for(let i=0; i<ps.length; i++){
            let pa = ps[i];
            let pax = pa.position.x;
            let pay = pa.position.y;
            let vax = pa.velocity.x;   // snapshot of A's velocity for this particle's pass
            let vay = pa.velocity.y;
            let s = start[i];
            let e = start[i+1];

            for(let k=s; k<e; k++){
                let pb = ps[nbr[k]];
                let rx = pb.position.x - pax;
                let ry = pb.position.y - pay;
                let d2 = rx*rx + ry*ry;
                if(d2 >= R2 || d2 < 1e-8){
                    continue;
                }
                let dist = Math.sqrt(d2);
                let nx = rx / dist;
                let ny = ry / dist;
                let u = (vax - pb.velocity.x) * nx + (vay - pb.velocity.y) * ny;
                let omq = 1 - dist * invR;

                // Relative motion = local turbulence -> nucleates foam at the splash.
                let stir = omq * Math.abs(u);
                pa.agitation += stir;
                pb.agitation += stir;
                // How buried each particle is (neighbours above it): ry<0 means B above A.
                if(ry < 0){ pa.cover += omq; }
                else{ pb.cover += omq; }

                if(u > 0){
                    let ITerm = dt * omq * (SIG * u + BET * u * u) * 0.5;
                    let ix = nx * ITerm;
                    let iy = ny * ITerm;
                    pa.velocity.x -= ix;
                    pa.velocity.y -= iy;
                    pb.velocity.x += ix;
                    pb.velocity.y += iy;
                }
            }
        }
    }

    worldBoundary(){
        let tableY = this.glass.center.y + this.glass.height * 0.5 + 2;
        for(let i=0; i< this.particles.length; i++){
            let p = this.particles[i];
            let pos = p.position;

            if(pos.x < 0){
                pos.x = 0;
                p.prevPosition.x = 0;
            }
            if(pos.y < 0){
                pos.y = 0;
                p.prevPosition.y = 0;
            }
            if(pos.x > canvas.width){
                pos.x = canvas.width-1;
                p.prevPosition.x = canvas.width-1;
            }
            // Spilled beer pools on the table the glass stands on, not the screen edge.
            if(pos.y > tableY && !this.isInsideGlassInterior(pos)){
                pos.y = tableY;
                p.prevPosition.y = tableY;
            }
            if(pos.y > canvas.height){
                pos.y = canvas.height-1;
                p.prevPosition.y = canvas.height-1;
            }
        }
    }

    trimParticles(){
        // Drop particles that have spilled off the table so they don't pile up forever.
        for(let i=this.particles.length - 1; i>=0; i--){
            let p = this.particles[i];
            if(p.position.y > canvas.height - 4 && !this.isInsideGlassInterior(p.position)){
                p.deadTimer = (p.deadTimer || 0) + 1;
                if(p.deadTimer > 90){
                    this.particles.splice(i, 1);
                }
            }
        }
        if(this.particles.length > this.MAX_PARTICLES){
            this.particles.splice(0, this.particles.length - this.MAX_PARTICLES);
        }
    }

    /* ---------- Foam ---------- */

    updateFoam(dt){
        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            p.age += dt;
            p.turbulence *= 0.95;

            // Turbulence above a quiescent threshold whips dissolved CO2 into foam.
            // Beer sliding gently down the wall stays below it -> almost no foam.
            // The stream plunging into the pool blows past it -> a thick head.
            let inGlass = this.isInsideGlassInterior(p.position);
            let stir = p.agitation - this.FOAM_THRESHOLD;
            if(stir > 0 && inGlass){
                // Turbulence whips up foam. A hard plunge churns a lot; beer sliding
                // gently down the wall barely crosses the threshold.
                p.foam = Math.min(1, p.foam + stir * this.FOAM_GEN * dt);
                if(stir > 950 && this.foamParticles.length < this.MAX_FOAM_PARTICLES && Math.random() < 0.02){
                    this.createFoamBurst(p.position, 0.4 + Math.min(1, stir * 0.0012));
                }
            }

            // Foam under a head of beer collapses fast (pressure); foam at the free
            // surface lasts. Buoyancy lifts foam up, so a head gathers on top and the
            // body below clears - the head thickness self-limits as lower bubbles burst.
            let decayRate = this.FOAM_DECAY * (1 + p.cover * p.cover * 0.6);
            if(!inGlass){
                decayRate += 0.09;   // spilled beer loses its foam (reads as amber, not white)
            }
            p.foam -= p.foam * decayRate * dt;
        }
    }

    createFoamBurst(position, intensity){
        let amount = Math.max(1, Math.floor(1 + intensity * 2.5));
        for(let i=0; i<amount && this.foamParticles.length < this.MAX_FOAM_PARTICLES; i++){
            let angle = Math.random() * Math.PI * 2;
            let radius = Math.random() * 8 * intensity;
            let pos = Add(position, new Vector2(Math.cos(angle) * radius, Math.sin(angle) * radius));
            let vel = new Vector2(
                (Math.random() - 0.5) * (9 + intensity * 7),
                -6 - Math.random() * (8 + intensity * 8)
            );
            let bubbleRadius = 3 + Math.random() * 4 + intensity * 2;
            let life = 0.5 + Math.random() * 0.6 + intensity * 0.4;
            this.foamParticles.push(new FoamParticle(pos, vel, bubbleRadius, life));
        }
    }

    // Airborne splash flecks thrown up by a hard pour; they arc up and fall back.
    updateFoamParticles(dt){
        for(let i=this.foamParticles.length - 1; i>=0; i--){
            let foam = this.foamParticles[i];
            foam.life -= dt * 0.14;

            if(foam.life <= 0){
                this.foamParticles.splice(i, 1);
                continue;
            }

            foam.prevPosition = foam.position.Cpy();
            foam.velocity.y += 1.7 * dt;
            foam.velocity.x += Math.sin(foam.seed + foam.life * 7.0) * 0.05;
            foam.velocity = Scale(foam.velocity, 0.985);
            foam.position = Add(foam.position, Scale(foam.velocity, dt));

            for(let j=0; j<this.shapes.length; j++){
                let dir = this.shapes[j].getDirectionOut(foam.position);
                if(dir != null){
                    foam.position = Add(foam.position, dir);
                    foam.velocity = Scale(foam.velocity, 0.5);
                }
            }

            if(foam.position.x < -20 || foam.position.x > canvas.width + 20 || foam.position.y > canvas.height + 40){
                this.foamParticles.splice(i, 1);
            }
        }
    }

    /* ---------- Rendering: beer & foam silhouettes (white on transparent) ---------- */

    drawBeer(targetCtx){
        let r = window.BEER_RADIUS;
        targetCtx.fillStyle = "white";
        targetCtx.globalAlpha = 1;

        for(let i=0; i < this.particles.length; i++){
            let p = this.particles[i];
            targetCtx.beginPath();
            targetCtx.arc(p.position.x, p.position.y, r, 0, Math.PI * 2);
            targetCtx.fill();
        }
    }

    drawFoam(targetCtx){
        targetCtx.fillStyle = "white";
        targetCtx.globalAlpha = 1;

        // The head IS the foamy beer particles, which buoyancy has floated to the top.
        // No scripted band - wherever foam physically is, that is where it draws.
        let r = window.FOAM_RADIUS;
        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            if(p.foam <= this.FOAM_RENDER_MIN){
                continue;
            }
            let f = Math.min(1, (p.foam - this.FOAM_RENDER_MIN) / (1 - this.FOAM_RENDER_MIN));
            targetCtx.beginPath();
            targetCtx.arc(p.position.x, p.position.y, r * (0.55 + f * 0.6), 0, Math.PI * 2);
            targetCtx.fill();
        }

        // Airborne splash flecks.
        for(let i=0; i<this.foamParticles.length; i++){
            let foam = this.foamParticles[i];
            let alpha = Math.max(0, Math.min(1, foam.life / foam.maxLife));
            let rr = foam.radius * (0.7 + (1 - alpha) * 0.3);

