class ParticleEmitter{
    constructor(position, direction, size, spawnInterval, amount, velocity){
        this.position = position;
        this.direction = direction;
        this.size = size;
        this.spawnInterval = spawnInterval;
        this.amount = amount;
        this.velocity = velocity;
        this.flowScale = 0;
        this.spread = 0.16;
        this.enabled = true;
        this.time = 0;
    }

    spawn(dt, particles, maxParticles, maxSpawnCount = Number.MAX_VALUE){
        if(!this.enabled || this.flowScale <= 0){
            return 0;
        }

        this.time += dt;
        let spawned = 0;
        let interval = Math.max(0.006, this.spawnInterval / Math.max(0.25, this.flowScale));

        while(this.time > interval && particles.length < maxParticles && spawned < maxSpawnCount){
            this.time -= interval;
            let amount = Math.max(1, Math.round(this.amount * this.flowScale));
            let offset = (this.size * 2) / Math.max(1, amount - 1);

            for(let i=0; i<amount && particles.length < maxParticles && spawned < maxSpawnCount; i++){
                let dir = this.direction.Cpy();
                dir.Normalize();

                let normal = dir.GetNormal();
                normal.Normalize();

                let planeStart = Add(this.position, Scale(normal, -this.size));
                let position = Add(planeStart, Scale(normal, offset * i));
                position = Add(position, Scale(normal, (Math.random() - 0.5) * 4));
                position = Add(position, Scale(dir, Math.random() * 5));

                let angle = (Math.random() - 0.5) * this.spread;
                let cosAngle = Math.cos(angle);
                let sinAngle = Math.sin(angle);
                let pourDir = new Vector2(
                    dir.x * cosAngle - dir.y * sinAngle,
                    dir.x * sinAngle + dir.y * cosAngle
                );

                let particle = new Particle(position);
                let speed = this.velocity * (0.88 + Math.random() * 0.24) * (0.92 + this.flowScale * 0.28);
                particle.velocity = Scale(pourDir, speed);
                particle.foam = Math.random() * 0.1;
                particles.push(particle);
                spawned++;
            }
        }

        return spawned;
    }

    rotate(angleInRadians){
        const cosAngle = Math.cos(angleInRadians);
        const sinAngle = Math.sin(angleInRadians);
        const rotatedX = this.direction.x * cosAngle - this.direction.y * sinAngle;
        const rotatedY = this.direction.x * sinAngle + this.direction.y * cosAngle;
        this.direction.x = rotatedX;
        this.direction.y = rotatedY;
    }

    move(delta){
        this.position = Add(this.position, delta);
    }

    draw(){
        let dir = this.direction.Cpy();
        dir.Normalize();

        let normal = dir.GetNormal();
        normal.Normalize();
        let plane = Scale(normal, -this.size);
        let planeStart = Add(this.position, plane);
        let planeEnd = Sub(this.position, plane);

        DrawUtils.drawLine(planeStart, planeEnd, "rgba(245,185,70,0.45)", 4);
    }
}

