function makeCtx(){ const gradient={addColorStop(){}}; return new Proxy({createLinearGradient(){return gradient},createRadialGradient(){return gradient}}, {get(o,p){return p in o?o[p]:function(){}}, set(o,p,v){o[p]=v;return true}}); }
function run(frames){
