  const leftY = grid.getSurfaceLocalYAtX(-grid.maxHalfWidth, 0);
  const midY = grid.getSurfaceLocalYAtX(0, 0);
  const rightY = grid.getSurfaceLocalYAtX(grid.maxHalfWidth, 0);
